const verifiedAgrees = `-- name: VerifiedAgrees :many
SELECT r.creator_id, r.rank, count(v.buyer_id)::int AS agrees FROM creator_reviews r
JOIN creator_votes v ON v.creator_review_id = r.id AND v.value = 1 AND v.updated_at >= $1 AND v.updated_at < $2
WHERE r.product_id = $3 AND r.status = 'PUBLISHED'
  AND EXISTS (SELECT 1 FROM order_items i JOIN sub_orders s ON s.id = i.sub_order_id JOIN orders o ON o.id = s.order_id
    JOIN variants vv ON vv.id = i.variant_id
    WHERE o.buyer_id = v.buyer_id AND vv.product_id = r.product_id AND s.status = 'DELIVERED' AND i.status IN ('ACTIVE', 'REPLACED'))
GROUP BY r.creator_id, r.rank ORDER BY r.rank
`

type VerifiedAgreesParams struct {
	PeriodStart time.Time `json:"periodStart"`
	PeriodEnd   time.Time `json:"periodEnd"`
	ProductID   uuid.UUID `json:"productId"`
}

type VerifiedAgreesRow struct {
	CreatorID uuid.UUID `json:"creatorId"`
	Rank      int32     `json:"rank"`
	Agrees    int32     `json:"agrees"`
}

// Agree votes cast in the period by buyers who still own a delivered purchase of the product (LLD 8.9).
func (q *Queries) VerifiedAgrees(ctx context.Context, arg VerifiedAgreesParams) ([]VerifiedAgreesRow, error) {
	rows, err := q.db.Query(ctx, verifiedAgrees, arg.PeriodStart, arg.PeriodEnd, arg.ProductID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VerifiedAgreesRow{}
	for rows.Next() {
		var i VerifiedAgreesRow
		if err := rows.Scan(&i.CreatorID, &i.Rank, &i.Agrees); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const voteCreatorReview = `-- name: VoteCreatorReview :exec
INSERT INTO creator_votes (creator_review_id, buyer_id, value) VALUES ($1, $2, $3)
ON CONFLICT (creator_review_id, buyer_id) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
`

type VoteCreatorReviewParams struct {
	CreatorReviewID uuid.UUID `json:"creatorReviewId"`
	BuyerID         uuid.UUID `json:"buyerId"`
	Value           int32     `json:"value"`
}

func (q *Queries) VoteCreatorReview(ctx context.Context, arg VoteCreatorReviewParams) error {
	_, err := q.db.Exec(ctx, voteCreatorReview, arg.CreatorReviewID, arg.BuyerID, arg.Value)
	return err
}
